#include <stdio.h>
#include <stdlib.h>

#define QUEUE_CAP 5

int main(int argc, char **argv)
{
    /* No arguments – print NOOP and exit */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    long items[QUEUE_CAP];   /* circular buffer */
    int head = 0;            /* index of front element */
    int count = 0;           /* number of elements stored */

    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];

        /* ENQUEUE: command starts with 'E' followed by a decimal number */
        if (cmd[0] == 'E') {
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);
            if (endptr == cmd + 1) {          /* no digits after 'E' */
                puts("ERR");
                continue;
            }
            if (count == QUEUE_CAP) {        /* queue full */
                puts("FULL");
                continue;
            }
            items[(head + count) % QUEUE_CAP] = val;  /* store at tail */
            ++count;
            printf("ENQ %ld\n", val);
            continue;
        }

        /* DEQUEUE: exactly "D" */
        if (cmd[0] == 'D' && cmd[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long val = items[head];
            head = (head + 1) % QUEUE_CAP;
            --count;
            printf("DEQ %ld\n", val);
            continue;
        }

        /* FRONT: exactly "F" */
        if (cmd[0] == 'F' && cmd[1] == '\0') {
            if (count == 0) {
                puts("EMPTY");
                continue;
            }
            long val = items[head];
            printf("FRONT %ld\n", val);
            continue;
        }

        /* Anything else is an error */
        puts("ERR");
    }

    return 0;
}
